  <h1>Pocket Garden</h1>
  <p class="lead">Three plants to start your garden.</p>
  <p class="notice">Your choices reset when you reload this page.</p>

  <div class="filters" role="group" aria-label="Filter plants by light">
    <button type="button" class="filter" data-filter="all" aria-pressed="true">All plants</button>
    <button type="button" class="filter" data-filter="sun" aria-pressed="false">Loves sun</button>
