      <button type="button" class="plant-btn" data-planted="false" aria-pressed="false"><span class="label">Mark as planted</span><span class="sr-only">: Basil</span></button>
    </article>

    <article class="card" data-light="sun" data-name="Sunflower">
      <span class="tag sun">Loves sun</span>
      <h2>Sunflower</h2>
      <p>A tall bloom that follows the light all day.</p>
      <button type="button" class="plant-btn" data-planted="false" aria-pressed="false"><span class="label">Mark as planted</span><span class="sr-only">: Sunflower</span></button>
    </article>

    <article class="card" data-light="shade" data-name="Mint">
      <span class="tag shade">Likes shade</span>
      <h2>Mint</h2>
      <p>A hardy herb that stays happy in cooler, shadier corners.</p>
      <button type="button" class="plant-btn" data-planted="false" aria-pressed="false"><span class="label">Mark as planted</span><span class="sr-only">: Mint</span></button>
    </article>
  </section>
</main>

<script>
(function () {
  var filterButtons = document.querySelectorAll('.filter');
  var cards = document.querySelectorAll('.card');
  var status = document.getElementById('status');

  function applyFilter(filter) {
    var shown = 0;
    cards.forEach(function (card) {
      var match = filter === 'all' || card.dataset.light === filter;
      card.hidden = !match;
      if (match) shown++;
    });
    filterButtons.forEach(function (btn) {
      btn.setAttribute('aria-pressed', String(btn.dataset.filter === filter));
    });
    status.textContent = 'Showing ' + shown + ' of ' + cards.length + ' plants.';
  }

  filterButtons.forEach(function (btn) {
    btn.addEventListener('click', function () { applyFilter(btn.dataset.filter); });
  });

  document.querySelectorAll('.plant-btn').forEach(function (btn) {
    btn.addEventListener('click', function () {
      var planted = btn.dataset.planted !== 'true';
      var card = btn.closest('.card');
      btn.dataset.planted = String(planted);
      btn.setAttribute('aria-pressed', String(planted));
      btn.classList.toggle('on', planted);
      card.classList.toggle('is-planted', planted);
      btn.querySelector('.label').textContent = planted ? 'Planted' : 'Mark as planted';
      status.textContent = card.dataset.name + (planted ? ' marked as planted.' : ' unmarked.');
    });
  });

  applyFilter('all');
})();
</script>
